import ast
import glob
import os

def test_test_file_names_match_modules():
    source_modules = [os.path.basename(f)[:-3] for f in glob.glob("*.py")] + \
                     [os.path.basename(f)[:-3] for f in glob.glob("plugins/*.py")]

    allowlist = [
        'tests/test_meta_markers.py', 'tests/test_meta_float_comparisons.py', 'tests/test_orchestration_retry.py', 'tests/test_meta_unittest_aliases.py', 'tests/test_webchat_config.py', 'tests/test_meta_asserts.py', 'tests/test_meta_magic_numbers.py', 'tests/test_imports.py', 'tests/test_meta_complexity.py', 'tests/test_webchat_parsing.py', 'tests/test_pytest_config.py', 'tests/test_noqa_meta.py', 'tests/test_meta_map_filter_lambda.py', 'tests/test_utm.py', 'tests/test_meta_except_handlers.py', 'tests/test_meta_subprocess_shell.py', 'tests/test_meta_all_defined.py', 'tests/test_module_docstrings.py', 'tests/test_meta_network_imports.py', 'tests/test_docs_snippets.py', 'tests/test_tile_helpers.py', 'tests/test_provider_edge_cases.py', 'tests/test_geohash.py', 'tests/test_no_print.py', 'tests/test_meta_float_comparison.py', 'tests/test_meta_dataclass_replace.py', 'tests/test_meta_sleep.py', 'tests/test_meta_type_compare.py', 'tests/test_citation.py', 'tests/test_meta_skip.py', 'tests/test_yamllint_workflow.py', 'tests/test_meta_yield_from.py', 'tests/test_manifest_icons.py', 'tests/test_meta_mktemp.py', 'tests/test_none_comparisons.py', 'tests/test_mercator.py', 'tests/test_todos.py', 'tests/test_snake_case_names.py', 'tests/test_meta_tests.py', 'tests/test_gitleaks_workflow.py', 'tests/test_meta_ast_is_literal.py', 'tests/test_ast_class_attributes.py', 'tests/test_meta_empty_tests.py', 'tests/test_docstrings.py', 'tests/test_readme.py', 'tests/test_newlines_eof.py', 'tests/test_meta_tabs.py', 'tests/test_bare_except.py', 'tests/test_meta_duplicate_methods.py', 'tests/test_meta_walrus.py', 'tests/test_meta_loops.py', 'tests/test_network_block.py', 'tests/test_meta_sys_path.py', 'tests/test_meta_module_length.py', 'tests/test_meta_yaml.py', 'tests/test_meta_verify.py', 'tests/test_no_globals.py', 'tests/test_meta_empty_except.py', 'tests/test_no_pickle.py', 'tests/test_meta_no_literal_write_paths.py', 'tests/test_actionlint_workflow.py', 'tests/test_meta_bool_compare.py', 'tests/test_random_seed_meta.py', 'tests/test_subprocess_ast.py', 'tests/test_star_imports.py', 'tests/test_meta_open_path.py', 'tests/test_provider_selection.py', 'tests/test_meta_logger_fstring.py', 'tests/test_meta_skip_reason.py', 'tests/test_meta_functions_nesting.py', 'tests/test_gitignore.py', 'tests/test_meta_logging_fstring.py', 'tests/test_webchat_map.py', 'tests/test_meta_type_ignore.py', 'tests/test_open_meta.py', 'tests/test_license.py', 'tests/test_meta_not_in.py', 'tests/test_meta_exit.py', 'tests/test_meta_pass_statement.py', 'tests/test_hashlib_security.py', 'tests/test_meta_assert_tuple.py', 'tests/test_ast_meta_raise_from.py', 'tests/test_meta_str_concat.py', 'tests/test_meta_three_arg_getattr.py', 'tests/test_bbox.py', 'tests/test_meta_no_os_chdir.py', 'tests/test_meta_len_comparison.py', 'tests/test_configuration.py', 'tests/test_line_length.py', 'tests/test_function_params.py', 'tests/test_meta.py', 'tests/test_meta_open_encoding.py', 'tests/test_meta_datetime.py', 'tests/test_meta_duplicate_names.py', 'tests/test_setattr_meta.py', 'tests/test_chained_assignment.py', 'tests/test_meta_tuple_assert.py', 'tests/test_nesting_meta.py', 'tests/test_chmod_meta.py', 'tests/test_wcag_ui.py', 'tests/test_meta_class_method_count.py', 'tests/test_meta_test_bare_return_fixture.py', 'tests/test_unreachable.py', 'tests/test_ast_lambdas.py', 'tests/test_manifest_json.py', 'tests/test_geocode_fallback.py', 'tests/test_os_environ_ast.py', 'tests/test_webchat_tables.py', 'tests/test_meta_fixture_sleep.py', 'tests/test_code_quality.py', 'tests/test_meta_capwords.py', 'tests/test_meta_docstring.py', 'tests/test_meta_finally_blocks.py', 'tests/test_deprecated_imports.py', 'tests/test_raster.py', 'tests/test_meta_swallowed_exceptions.py', 'tests/test_raise_not_implemented.py', 'tests/test_meta_del.py', 'tests/test_plugins_init.py', 'tests/test_meta_secrets.py', 'tests/test_security_eval_exec.py', 'tests/test_meta_relative_imports.py', 'tests/test_agents_md.py', 'tests/test_meta_logging.py', 'tests/test_pip_check_workflow.py', 'tests/test_nesting.py', 'tests/test_meta_dict_assignment.py', 'tests/test_meta_tarfile_extraction.py', 'tests/test_import_order.py', 'tests/test_crs.py', 'tests/test_meta_pep604_annotations.py', 'tests/test_mutable_defaults.py', 'tests/test_meta_input.py', 'tests/test_meta_debug_statements.py', 'tests/test_meta_ast_nonlocal.py', 'tests/test_manifest_link.py', 'tests/test_meta_no_print_in_tests.py', 'tests/test_meta_dict_keys.py', 'tests/test_os_system_calls.py', 'tests/test_meta_print_outside_entry.py', 'tests/test_fstring_meta.py', 'tests/test_meta_unittest_testcase.py', 'tests/test_meta_tmp.py', 'tests/test_meta_base_exception.py', 'tests/test_webchat_infer.py', 'tests/test_hardcoded_paths.py', 'tests/test_ast_subprocess.py', 'tests/test_index_html.py', 'tests/test_meta_test_names.py'
    ]

    offenders = []
    for test_file in glob.glob("tests/test_*.py"):
        with open(test_file, "r") as f:
            try:
                tree = ast.parse(f.read(), filename=test_file)
            except SyntaxError:
                continue

        test_name = os.path.basename(test_file)
        if test_name.startswith("test_") and test_name.endswith(".py"):
            base_name = test_name[5:-3]
            if base_name not in source_modules:
                offenders.append(test_file)

    new_offenders = [o for o in offenders if o not in allowlist]
    assert not new_offenders, f"Found {len(new_offenders)} new test files whose name does not match any source module: {new_offenders}"
    assert len(offenders) <= len(allowlist), f"Total test files without matching source module grew to {len(offenders)}, beyond allowlist of {len(allowlist)}"
